function renderAttemptStats(){$('aCurrent').textContent=`${currentStreak()} giorni`;$('aBest').textContent=`${bestStreak()} giorni`;$('aResets').textContent=resetCount();$('aTotal').textContent=globalCompletedDays();$('aDay').textContent=state.attempt?`${dayNumber()} / 90`:'1 / 90';$('aCalendar').textContent=calendarDays()}
function renderAttemptHistory(){const box=$('attemptHistory');if(!box)return;const rows=attemptRows();if(!rows.length){box.innerHTML='<div class="empty">Nessun tentativo registrato.</div>';return}box.innerHTML='<table class="attemptTable"><thead><tr><th>Tentativo</th><th>Data inizio</th><th>Giorni consecutivi</th><th>Data interruzione</th><th>Motivo</th><th>Appuntamenti svolti</th><th>Contratti firmati</th></tr></thead><tbody>'+rows.map(a=>{const active=String(a.status).toUpperCase()==='ACTIVE',m=a.metadata||{},res=active?resultsForWindow(dateKey(a.starts_at)):null;return `<tr><td>${m.attempt_number||'—'}</td><td>${fmtDate(dateKey(a.starts_at))}</td><td>${active?currentStreak():Number(m.consecutive_days||m.completed_days)||0}${active?' · in corso':''}</td><td>${active?'—':fmtDate(m.interruption_date||dateKey(a.ends_at))}</td><td>${active?'IN CORSO':esc(String(m.interruption_reason||a.status||'').replaceAll('_',' '))}</td><td>${active?res.appointments.length:Number(m.appointments_real)||0}</td><td>${active?res.contracts.length:Number(m.contracts_signed)||0}</td></tr>`}).join('')+'</tbody></table>'}
function attemptActivityReview(){const start=attemptStart(),end=addDays(start,29),ints=state.interactions.filter(i=>dateKey(i.occurred_at)>=start&&dateKey(i.occurred_at)<=end),followIds=new Set(state.tasks.filter(t=>String(t.task_type||'').toUpperCase()==='FOLLOW_UP').map(t=>String(t.task_id))),calls=ints.filter(i=>String(i.interaction_type||'').toUpperCase()==='CALL'&&String(i.direction||'OUTBOUND').toUpperCase()==='OUTBOUND'),noTalk=/NON[ _-]?RISPONDE|NO[ _-]?ANSWER|SEGRETERIA|VOICEMAIL|NESSUNA[ _-]?RISPOSTA/i,conversations=calls.filter(i=>i.outcome&&!noTalk.test(String(i.outcome))),followups=new Set(ints.filter(i=>followIds.has(String(i.task_id||''))).map(i=>String(i.task_id))).size,leads=state.leads.filter(l=>dateKey(l.created_at)>=start&&dateKey(l.created_at)<=end).length,preview=new Set(state.events.filter(e=>e.event_type==='MARKET_PREVIEW_VISIONED'&&dateKey(e.occurred_at)>=start&&dateKey(e.occurred_at)<=end).map(e=>e.property_id).filter(Boolean)).size;let scriptSec=0;for(const d of dayRows(state.attempt?.campaign_id||'')){if(d.territory_key<start||d.territory_key>end)continue;scriptSec+=Number(normalizedBlocks(d.metadata).script.elapsed_seconds)||0}const r=first30Results();return{calls:calls.length,conversations:conversations.length,leads,followups,preview,scriptHours:(scriptSec/3600).toFixed(1),appointments:r.appointments.length,contracts:r.contracts.length,apptSources:sourceSummary(r.appointments),contractSources:sourceSummary(r.contracts)}}
function renderReview30(){const box=$('review30Panel');if(!box)return;box.hidden=!state.attempt||dayNumber()<30;if(box.hidden)return;const r=attemptActivityReview();$('review30Body').innerHTML=`<div class="attemptGrid"><div class="attemptBox"><b>4</b><span>APPUNTAMENTI TARGET</span></div><div class="attemptBox"><b>${r.appointments}</b><span>APPUNTAMENTI REALI</span></div><div class="attemptBox"><b>2</b><span>CONTRATTI TARGET</span></div><div class="attemptBox"><b>${r.contracts}</b><span>CONTRATTI REALI</span></div><div class="attemptBox"><b>${r.calls}</b><span>CONTATTI EFFETTUATI</span></div><div class="attemptBox"><b>${r.conversations}</b><span>CONVERSAZIONI</span></div><div class="attemptBox"><b>${r.leads}</b><span>LEAD GENERATI</span></div><div class="attemptBox"><b>${r.followups}</b><span>FOLLOW-UP</span></div><div class="attemptBox"><b>${r.preview}</b><span>PREVIEW IMMOBILI</span></div><div class="attemptBox"><b>${r.scriptHours}h</b><span>ORE SCRIPT</span></div></div><p class="meta"><b>Fonte appuntamenti:</b> ${esc(r.apptSources)}<br><b>Fonte contratti:</b> ${esc(r.contractSources)}</p>`}
function renderCloseChecklist(){const box=$('closeChecklist');if(!box)return;const c=dayChecks(),labels={script:'SCRIPT / ROLE-PLAY',prospecting:'PROSPECTING',preview:'MARKET PREVIEW',followup:'FOLLOW-UP'};box.innerHTML=Object.entries(labels).map(([k,l])=>`<div class="${c[k]?'yes':'no'}"><b>${l}</b><br>${c[k]?'COMPLETATO':'NON COMPLETATO'}</div>`).join('')}
function renderClosed(){if(!state.day)return;const status=state.day.metadata?.close_status||'';$('dayState').textContent=String(state.day.status).toUpperCase()==='CLOSED'?`GIORNATA CHIUSA · ${status}`:'GIORNATA ATTIVA';if(String(state.day.status).toUpperCase()==='CLOSED'){$('closeResult').className='closeResult '+(status==='COMPLETATA'?'ok':'warn');if(!$('closeResult').innerHTML)$('closeResult').innerHTML=`<b>${esc(status)}</b>${(state.day.metadata?.missing||[]).length?'<br>'+state.day.metadata.missing.map(x=>'• '+esc(x)).join('<br>'):''}`}}
function render(){renderSetup();if(!state.program)return;installEnhancedUI();renderHeader();if(state.day){renderBlocks();renderKpis();renderFollowups();renderNoAppointment();renderCloseChecklist();renderClosed()}renderGoal30();renderAttemptStats();renderAttemptHistory();renderReview30();renderWeekly();renderReview();renderOptimization();if(!state.attempt){$('dayState').textContent='PIANO INTERROTTO — RIPARTENZA DAL GIORNO 1';$('closeDay').disabled=true}}
function bind(){$('startProgram').onclick=startProgram;$('closeDay').onclick=closeDay;$('logRoleplay').onclick=logRoleplay;$('saveReview').onclick=saveReview;document.querySelectorAll('[data-block]').forEach(card=>{const k=card.dataset.block;card.querySelector('[data-act="start"]').onclick=()=>startBlock(k);card.querySelector('[data-act="pause"]').onclick=()=>pauseBlock(k);card.querySelector('[data-act="complete"]').onclick=()=>completeBlock(k)});state.timer=setInterval(()=>{if(state.day&&Object.values(normalizedBlocks(state.day.metadata)).some(b=>b.started_at)){renderHeader();renderBlocks();renderKpis();renderWeekly();renderCloseChecklist()}},1000)}
window.F190={state,PROGRAM,DAY,ATTEMPT,BLOCKS,NO_APPT_ORIGIN,RESULT_ORIGIN,load,metricsFor,dayNumber,calendarDays,currentStreak,bestStreak,resetCount,globalCompletedDays,first30Results,resultKind,target30Status,contactGoal,closeChecks,scheduledAppointments,hasScheduledAppointment,noAppointmentRequired,noAppointmentVisits,ownerCandidates,recordNoAppointmentVisit,recordActualResult,dayChecks};
